ALTER TABLE public.subscription_plans ADD COLUMN perks text[] NOT NULL DEFAULT '{}';
UPDATE public.subscription_plans SET perks=ARRAY['Every chapter Q-bank in your included subjects','Detailed answers and explanations','Image-based questions by chapter','Bookmarks and Mistake vault for revision','Practise whole subjects and sections','Review attempts after each Q-bank','Daily Blitz, streaks and progress statistics','Android app and website access on two devices'];
CREATE OR REPLACE FUNCTION public.admin_save_plan_full(_id text,_name text,_description text,_year integer,_two_year integer,_original_year integer,_original_two_year integer,_enabled boolean,_subjects text[],_perks text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF _perks IS NULL OR cardinality(_perks)>20 OR EXISTS(SELECT 1 FROM unnest(_perks) p WHERE length(btrim(p)) NOT BETWEEN 1 AND 300) THEN RAISE EXCEPTION 'Use up to 20 benefits of 1–300 characters'; END IF; PERFORM public.admin_save_plan(_id,_name,_description,_year,_two_year,_original_year,_original_two_year,_enabled,_subjects); UPDATE public.subscription_plans SET perks=_perks WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.admin_save_plan_full(text,text,text,integer,integer,integer,integer,boolean,text[],text[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_save_plan_full(text,text,text,integer,integer,integer,integer,boolean,text[],text[]) TO authenticated;